      "rationale": "Directly falsifies the requirement that each step's output is quantized to 2dp (ROUND_HALF_EVEN) before being fed into the next step, by comparing impl's output against a reference that performs exactly that quantize-then-feed-forward algorithm using decimal.Decimal — any implementation that instead accumulates full-precision intermediates and rounds only once at the end will diverge on many generated multi-step percent-discount chains.",
      "code": "import impl
from decimal import Decimal, ROUND_HALF_EVEN
from hypothesis import given, strategies as st, settings

subtotal_strategy = st.decimals(
    min_value=Decimal("0.01"), max_value=Decimal("1000.00"),
    places=2, allow_nan=False, allow_infinity=False,
)
percent_strategy = st.decimals(
    min_value=Decimal("0.00"), max_value=Decimal("100.00"),
    places=2, allow_nan=False, allow_infinity=False,
)


@given(
    subtotal=subtotal_strategy,
    values=st.lists(percent_strategy, min_size=2, max_size=3),
)
@settings(max_examples=100)
def test_quantizes_running_total_after_every_discount_step(subtotal, values):
    discounts = [{"kind": "percent", "value": str(v)} for v in values]

    # Reference: quantize to 2dp with ROUND_HALF_EVEN after each step,
    # feeding the quantized figure (not full precision) into the next step.
    running = subtotal
    for d in discounts:
        factor = Decimal("1") - Decimal(d["value"]) / Decimal("100")
        running = (running * factor).quantize(Decimal("0.01"), rounding=ROUND_HALF_EVEN)
    expected = str(running)

    result = impl.apply_discounts(str(subtotal), discounts)
    assert result == expected
